(async()=>{
  const E=__echoes;
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  const o={};
  o.openAfterB=!!document.querySelector('#socket-screen.nd-open');
  o.style=(()=>{const el=document.querySelector('#socket-screen');return el?getComputedStyle(el).display:null;})();
  const t0=E.tick;
  await sleep(3200);
  o.auraPulses=E.events.filter(e=>e.tick>=t0&&e.type==='aura_pulse').length;
  o.bounceHops=E.events.filter(e=>e.tick>=t0&&e.type==='bounce_hop').length;
  o.auraHealSources=[...new Set(E.events.filter(e=>e.tick>=t0&&e.type==='heal').map(e=>e.source))];
  // combat lock
  o.room=E.cmd('startRoom','kill_all');
  await sleep(300);
  o.combatActive=E.cmd('buildView').combatActive;
  o.closeThenOpen=E.cmd('closeSocket');
  o.openDenied=E.cmd('openSocket');
  o.socketDuringCombat=E.cmd('socket','mending_bolt','sharpen',0);
  o.denials=E.events.filter(e=>e.type==='socket_denied');
  return JSON.stringify(o);
})()
